using MovieInfoBackend.DataModels;
using Xunit.Abstractions;

public class TmdbTvSeriesDataModelTests
{
    private string tmdbHttpClientTvSeriesAggregateCreditsResponse;
    private string tmdbHttpClientTvSeriesResponse;

    public TmdbTvSeriesDataModelTests(ITestOutputHelper output)
    {
        // Arrange

        string testTvSeriesAggregateCreditsDataFilename = "TmdbHttpClientTvSeriesAggregateCreditsResponse.json";
        string testTvSeriesDataFilename = "TmdbHttpClientTvSeriesResponse.json";

        using (StreamReader sr = File.OpenText($"../../../TestData/{testTvSeriesAggregateCreditsDataFilename}"))
        {
            tmdbHttpClientTvSeriesAggregateCreditsResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientTvSeriesAggregateCreditsResponse))
        {
            throw new ArgumentException($"{testTvSeriesAggregateCreditsDataFilename} is not valid test data.");
        }

        using (StreamReader sr = File.OpenText($"../../../TestData/{testTvSeriesDataFilename}"))
        {
            tmdbHttpClientTvSeriesResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientTvSeriesResponse))
        {
            throw new ArgumentException($"{testTvSeriesDataFilename} is not valid test data.");
        }
    }

    [Fact]
    public void GetModelFromResponse_ValidResponse_ReturnsValidModels()
    {
        // Act
        
        TmdbTvSeriesAggregateCreditsResponseDataModel? tvSeriesAggregateCreditsResponse = TmdbHttpClient.GetTvSeriesAggregateCreditsModelFromResponse(tmdbHttpClientTvSeriesAggregateCreditsResponse);
        TmdbTvSeriesResponseDataModel? tvSeriesResponse = TmdbHttpClient.GetTvSeriesModelFromResponse(tmdbHttpClientTvSeriesResponse);

        // Assert

        // TV series aggregate credits
        Assert.NotNull(tvSeriesAggregateCreditsResponse);
        // Credits cast
        Assert.NotEmpty(tvSeriesAggregateCreditsResponse.Cast);
        TmdbTvSeriesAggregateCastDataModel firstCreditsCast = tvSeriesAggregateCreditsResponse.Cast[0];
        Assert.True(firstCreditsCast.Gender >= 0, "TV series credits cast Gender must not be a negative number");
        Assert.True(firstCreditsCast.Id > 0, "TV series credits cast Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCast.KnownForDepartment), "TV series credits cast KnownForDepartment must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCast.Name), "TV series credits cast Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCast.OriginalName), "TV series credits cast OriginalName must not be empty");
        Assert.True(firstCreditsCast.Popularity >= 0.0, "TV series credits cast Popularity must not be a negative decimal number");
        // Credits cast roles
        Assert.NotEmpty(firstCreditsCast.Roles);
        TmdbTvSeriesAggregateCastRoleDataModel firstCreditsCastFirstRole = firstCreditsCast.Roles[0];
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCastFirstRole.CreditId), "TV series credits cast first role CreditId must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCastFirstRole.Character), "TV series credits cast first role Character must not be empty");
        Assert.True(firstCreditsCastFirstRole.EpisodeCount > 0, "TV series credits cast first role EpisodeCount must be a positive number");
        Assert.True(firstCreditsCast.TotalEpisodeCount > 0, "TV series credits cast TotalEpisodeCount must be a positive number");
        Assert.True(firstCreditsCast.Order >= 0, "TV series credits cast Order must not be a negative number");
        // End credits cast
        // Credits crew
        Assert.NotEmpty(tvSeriesAggregateCreditsResponse.Crew);
        TmdbTvSeriesAggregateCrewDataModel firstCreditsCrew = tvSeriesAggregateCreditsResponse.Crew[0];
        Assert.True(firstCreditsCrew.Gender >= 0, "TV series credits crew Gender must not be a negative number");
        Assert.True(firstCreditsCrew.Id > 0, "TV series credits crew Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCrew.KnownForDepartment), "TV series credits crew KnownForDepartment must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCrew.Name), "TV series credits crew Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCrew.OriginalName), "TV series credits crew OriginalName must not be empty");
        Assert.True(firstCreditsCrew.Popularity >= 0.0, "TV series credits crew Popularity must not be a negative decimal number");
        // Credits crew jobs
        Assert.NotEmpty(firstCreditsCrew.Jobs);
        TmdbTvSeriesAggregateCrewJobDataModel firstCreditsCrewFirstJob = firstCreditsCrew.Jobs[0];
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCrewFirstJob.CreditId), "TV series credits crew first job CreditId must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCrewFirstJob.Job), "TV series credits crew first job Job must not be empty");
        Assert.True(firstCreditsCrewFirstJob.EpisodeCount > 0, "TV series credits crew first job EpisodeCount must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstCreditsCrew.Department), "TV series credits crew Department must not be empty");
        Assert.True(firstCreditsCast.TotalEpisodeCount > 0, "TV series credits crew TotalEpisodeCount must be a positive number");
        // End credits crew
        Assert.True(tvSeriesAggregateCreditsResponse.Id > 0, "TV series credits Id must be a positive number");

        // TV series
        Assert.NotNull(tvSeriesResponse);
        Assert.False(String.IsNullOrWhiteSpace(tvSeriesResponse.BackdropPath), "TV series BackdropPath must not be empty");
        // Created by
        Assert.NotEmpty(tvSeriesResponse.CreatedBy);
        TmdbCreatorDataModel firstCreator = tvSeriesResponse.CreatedBy[0];
        Assert.True(firstCreator.Id > 0, "TV series creator Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstCreator.CreditId), "TV series creator CreditId must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCreator.Name), "TV series creator Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCreator.OriginalName), "TV series creator OriginalName must not be empty");
        Assert.True(firstCreator.Gender >= 0, "TV series creator Gender must not be a negative number");
        // End created by
        Assert.NotEmpty(tvSeriesResponse.EpisodeRunTime);
        int firstEpisodeRunTime = tvSeriesResponse.EpisodeRunTime[0];
        Assert.True(firstEpisodeRunTime > 0, "TV series first EpisodeRunTime must be a positive number");
        Assert.NotEmpty(tvSeriesResponse.Genres);  // no need to test members since it is handled in a separate test suite, TmdbGenreDataModelTests
        Assert.True(tvSeriesResponse.Id > 0, "TV series Id must be a positive number");
        Assert.NotEmpty(tvSeriesResponse.Languages);
        Assert.False(String.IsNullOrWhiteSpace(tvSeriesResponse.Name), "TV series Name must not be empty");
        // Networks
        if (tvSeriesResponse.Networks.Length > 0)
        {
            TmdbNetworkDataModel firstNetwork = tvSeriesResponse.Networks[0];
            Assert.True(firstNetwork.Id > 0, "TV series network Id must be a positive number");
            Assert.False(String.IsNullOrWhiteSpace(firstNetwork.Name), "TV series network Name must not be empty");
            Assert.False(String.IsNullOrWhiteSpace(firstNetwork.OriginCountry), "TV series network OriginCountry must not be empty");
        }
        Assert.True(tvSeriesResponse.NumberOfEpisodes > 0, "TV series NumberOfEpisodes must be a positive number");
        Assert.True(tvSeriesResponse.NumberOfSeasons > 0, "TV series NumberOfSeasons must be a positive number");
        Assert.NotEmpty(tvSeriesResponse.OriginCountry);
        Assert.False(String.IsNullOrWhiteSpace(tvSeriesResponse.OriginalLanguage), "TV series OriginalLanguage must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(tvSeriesResponse.OriginalName), "TV series OriginalName must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(tvSeriesResponse.Overview), "TV series Overview must not be empty");
        Assert.True(tvSeriesResponse.Popularity >= 0.0, "TV series Popularity must not be a negative decimal number");
        Assert.False(String.IsNullOrWhiteSpace(tvSeriesResponse.PosterPath), "TV series PosterPath must not be empty");
        // Production companies
        Assert.NotEmpty(tvSeriesResponse.ProductionCompanies);
        TmdbProductionCompanyDataModel firstProductionCompany = tvSeriesResponse.ProductionCompanies[0];
        Assert.True(firstProductionCompany.Id > 0, "TV series production company Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstProductionCompany.Name), "TV series production company Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstProductionCompany.OriginCountry), "TV series production company OriginalName must not be empty");
        // End production companies
        // Production countries
        Assert.NotEmpty(tvSeriesResponse.ProductionCountries);
        TmdbProductionCountryDataModel firstProductionCountry = tvSeriesResponse.ProductionCountries[0];
        Assert.False(String.IsNullOrWhiteSpace(firstProductionCountry.Iso31661), "TV series production country Iso31661 must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstProductionCountry.Name), "TV series production country Name must not be empty");
        // End production countries
        // Seasons
        Assert.NotEmpty(tvSeriesResponse.Seasons);
        TmdbTvSeasonDataModel firstSeason = tvSeriesResponse.Seasons[0];
        Assert.True(firstSeason.EpisodeCount > 0, "TV series first season EpisodeCount must be a positive number");
        Assert.True(firstSeason.Id > 0, "TV series first season Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstSeason.Name), "TV series first season Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstSeason.Overview), "TV series first season Overview must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstSeason.PosterPath), "TV series first season PosterPath must not be empty");
        Assert.True(firstSeason.SeasonNumber > 0, "TV series first season SeasonNumber must be a positive number");
        Assert.True(firstSeason.VoteAverage >= 0.0, "TV series first season VoteAverage must not be a negative decimal number");
        // End seasons
        // Spoken languages
        Assert.NotEmpty(tvSeriesResponse.SpokenLanguages);
        TmdbSpokenLanguageDataModel firstSpokenLanguage = tvSeriesResponse.SpokenLanguages[0];
        Assert.False(String.IsNullOrWhiteSpace(firstSpokenLanguage.EnglishName), "TV series first spoken language EnglishName must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstSpokenLanguage.Iso6391), "TV series first spoken language Iso6391 must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstSpokenLanguage.Name), "TV series first spoken language Name must not be empty");
        // End spoken languages
        Assert.False(String.IsNullOrWhiteSpace(tvSeriesResponse.Status), "TV series Status must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(tvSeriesResponse.Tagline), "TV series Tagline must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(tvSeriesResponse.Type), "TV series Type must not be empty");
        Assert.True(tvSeriesResponse.VoteAverage >= 0.0, "TV series VoteAverage must not be a negative decimal number");
        Assert.True(tvSeriesResponse.VoteCount >= 0, "TV series VoteCount must not be a negative number");
    }

